import React,{useEffect,useState}from'react';
import{ActivityIndicator,Alert,Image,Modal,Platform,Pressable,SafeAreaView,ScrollView,StatusBar,StyleSheet,Text,TextInput,TouchableOpacity,View}from'react-native';
import{MaterialCommunityIcons as Icon}from'@expo/vector-icons';
