const API=Platform.OS==='android'?'http://10.0.2.2:8080':'http://localhost:8080';
const IMAGE_BASE='https://raw.githubusercontent.com/Sathya2346/employeemanagement/feature/react-native-mobile/src/main/resources/static/images';
const C={loginBg:'#f9fdfb',green:'#10b981',light:'#d1fae5',sidebar:'#23d2aa',active:'#50d2b3',bg:'#f5f9f8',white:'#fff',text:'#111',muted:'#6c757d',border:'#e5e5e5',orange:'#FF7423',danger:'#dc3545',purple:'#6f42c1',blue:'#0d6efd'};
const ADMIN=[['Overview','home-outline'],['Add Employee','account-plus-outline'],['Employee List','account-outline'],['Pending Onboarding','clipboard-check-outline'],['Attendance','clock-outline'],['Leave','calendar-outline'],['Hourly Reports','format-list-checks'],['Notifications','bell-outline'],['Settings','cog-outline'],['Logout','logout']];
